package com.quincaisoft.branch.web;import com.quincaisoft.branch.api.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import java.util.*;@RestController public class BranchController{private final BranchService service;public BranchController(BranchService service){this.service=service;}@GetMapping("/api/v1/branches")@PreAuthorize("isAuthenticated()")public List<BranchService.Item> list(){return service.list();}}